package com.focusflow.api.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="users") public class AppUser { @Id @GeneratedValue(strategy=GenerationType.UUID) public String id; @Column(nullable=false) public String name; @Column(nullable=false,unique=true) public String email; @Column(nullable=false) public String password; public Instant createdAt=Instant.now(); }
